import numpy as np
from scipy import stats
import sys

def extract_data(log_file):
    temps = []
    dens = []
    in_section = 0
    temp_idx = -1
    dens_idx = -1

    with open(log_file, 'r') as f:
        for line in f:
            line = line.strip()
            if 'Step' in line or 'Time' in line:
                in_section = 1
                parts = line.split()
                for i, p in enumerate(parts):
                    if p == 'Temp' or p == 'Temperature':
                        temp_idx = i
                    if p == 'Density' or p == 'density':
                        dens_idx = i
                continue
            if in_section == 1 and (line.startswith('Loop') or line.startswith('---') or line == ''):
                in_section = 0
                continue
            if in_section == 1 and temp_idx >= 0 and dens_idx >= 0:
                try:
                    parts = line.split()
                    if len(parts) > max(temp_idx, dens_idx):
                        temps.append(float(parts[temp_idx]))
                        dens.append(float(parts[dens_idx]))
                except:
                    pass
    return np.array(temps), np.array(dens)

def find_tg(temps, dens):
    idx = np.argsort(temps)
    temps = temps[idx]
    dens = dens[idx]

    best_tg = None
    best_score = -1e10
    n = len(temps)

    for i in range(int(n*0.2), int(n*0.8)):
        t_high = temps[i:]
        d_high = dens[i:]
        t_low = temps[:i]
        d_low = dens[:i]

        if len(t_high) < 3 or len(t_low) < 3:
            continue

        m1, b1, r1, _, _ = stats.linregress(t_high, d_high)
        m2, b2, r2, _, _ = stats.linregress(t_low, d_low)

        score = (r1**2 + r2**2) * abs(m1 - m2)

        if score > best_score:
            best_score = score
            if abs(m1 - m2) > 1e-10:
                best_tg = (b2 - b1) / (m1 - m2)

    return best_tg

log_path = '/results/6_Nov_Optimised/claude_45/react/quenching/subtask_true/level_1/workflow/sio2_quenching_1_subtask_quenching_trial_1/quench.log'
temps, dens = extract_data(log_path)
print(f'Found {len(temps)} points')
if len(temps) > 0:
    print(f'Temp range: {temps.min():.2f} - {temps.max():.2f} K')
    tg = find_tg(temps, dens)
    if tg:
        print(f'Tg = {tg:.2f} K')
